#include <vector>
#include <unordered_map>
#include <cmath>
#include <algorithm>

class Solution {
public:
    std::vector<int> findTaxicabNumbers(int n) {
        std::unordered_map<int, int> counts;
        int limit = std::cbrt(n) + 2;
        for (int a = 1; a < limit; ++a) {
            long long a3 = 1LL * a * a * a;
            if (a3 >= n) break;
            for (int b = a; b < limit; ++b) {
                long long s = a3 + 1LL * b * b * b;
                if (s > n) break;
                counts[s]++;
            }
        }
        std::vector<int> res;
        for (const auto& [s, c] : counts) {
            if (c >= 2) res.push_back(s);
        }
        std::sort(res.begin(), res.end());
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findTaxicabNumbers(int n) {
        Map<Integer, Integer> counts = new HashMap<>();
        int limit = (int) Math.cbrt(n) + 2;
        for (int a = 1; a < limit; a++) {
            long a3 = (long) a * a * a;
            if (a3 >= n) break;
            for (int b = a; b < limit; b++) {
                long s = a3 + (long) b * b * b;
                if (s > n) break;
                counts.put((int) s, counts.getOrDefault((int) s, 0) + 1);
            }
        }
        List<Integer> res = new ArrayList<>();
        for (var entry : counts.entrySet()) {
            if (entry.getValue() >= 2) res.add(entry.getKey());
        }
        Collections.sort(res);
        return res;
    }
}

function findTaxicabNumbers(n) {
    const counts = new Map();
    const limit = Math.floor(Math.cbrt(n)) + 2;
    for (let a = 1; a < limit; a++) {
        const a3 = a * a * a;
        if (a3 >= n) break;
        for (let b = a; b < limit; b++) {
            const s = a3 + b * b * b;
            if (s > n) break;
            counts.set(s, (counts.get(s) || 0) + 1);
        }
    }
    const res = [];
    for (const [s, c] of counts.entries()) {
        if (c >= 2) res.push(s);
    }
    return res.sort((x, y) => x - y);
}
